@dataclass
class ListRecord:
    key: str | None = None
    name: str = ''
    description: str = ''
    seeds: list[SeedDict | str] = field(default_factory=list)

    @staticmethod
    def normalize_input_seed(seed: SeedDict | str) -> SeedDict | str:
        if isinstance(seed, str):
